def find_ais(n=13):
    from itertools import permutations  # but too slow
    # better backtrack
    def backtrack(seq, used, diffs):
        if len(seq) == n:
            return seq
        for next_val in range(n):
            if next_val not in used:
                diff = abs(seq[-1] - next_val)
                if diff not in diffs and diff != 0:
                    seq.append(next_val)
                    used.add(next_val)
                    diffs.add(diff)
                    res = backtrack(seq, used, diffs)
                    if res:
                        return res
                    seq.pop()
                    used.remove(next_val)
                    diffs.remove(diff)
        return None

    for start in range(n):  # try different starts? but fix to 0
        seq = [0]
        used = {0}
        diffs = set()
        res = backtrack(seq, used, diffs)
        if res:
            return res
    return "UNSATISFIABLE"

